#include <iostream>
#include <cstring>
using namespace std;

class DynamicString {
private:
    char* data;
    size_t length;

public:
    DynamicString() : data(nullptr), length(0) {
        data = new char[1];
        data[0] = '\0';
        length = 0;
    }

    DynamicString(const char* str) {
        if (str == nullptr) {
            data = new char[1];
            data[0] = '\0';
            length = 0;
        } else {
            length = strlen(str);
            data = new char[length + 1];
            strcpy(data, str);
        }
    }

    DynamicString(const DynamicString& other) {
        length = other.length;
        data = new char[length + 1];
        strcpy(data, other.data);
    }

    ~DynamicString() {
        delete[] data;
    }

    DynamicString& operator=(const DynamicString& other) {
        if (this == &other) {
            return *this;
        }

        delete[] data;

        length = other.length;
        data = new char[length + 1];
        strcpy(data, other.data);

        return *this;
    }

    DynamicString& operator=(const char* str) {
        if (data && strcmp(data, str) == 0) {
            return *this;
        }

        delete[] data;

        if (str == nullptr) {
            data = new char[1];
            data[0] = '\0';
            length = 0;
        } else {
            length = strlen(str);
            data = new char[length + 1];
            strcpy(data, str);
        }

        return *this;
    }

    void print() const {
        cout << "After Assignment: " << data << endl;
    }
};

int main() {
    string first, second;
    getline(cin, first);
    getline(cin, second);

    DynamicString ds;
    ds = first.c_str();
    ds = second.c_str();
    ds.print();

    return 0;
}
